-- RLS step 3, area 1: payroll.
--
-- Adds has_module_permission(module, action), which mirrors mergePermissions in
-- lib/permissions.ts: a per-user override in profiles.permissions wins per action,
-- otherwise the role default applies, otherwise false. The defaults below must equal
-- DEFAULT_PERMISSIONS; lib/__tests__/rls-module-permission-defaults.test.ts fails if
-- they drift. Update both together.
--
-- payroll_runs then follows the "payslips" module, the same module that gates the
-- /payroll and /payslips pages. Service role (API routes, crons) bypasses RLS.
--
-- Rollback:
--   drop policy if exists payroll_runs_select on public.payroll_runs; (and _insert/_update/_delete)
--   create policy payroll_runs_authenticated_all on public.payroll_runs
--     for all to authenticated using (true) with check (true);

create or replace function public.has_module_permission(p_module text, p_action text)
returns boolean
language sql
stable
security definer
set search_path = public
as $fn$
  select coalesce(
    (p.permissions -> p_module ->> p_action)::boolean,
    (d.defaults -> p.role -> p_module ->> p_action)::boolean,
    false
  )
  from public.profiles p
  cross join (select
