revoke execute on function public.has_module_permission(text, text) from public, anon;
grant execute on function public.has_module_permission(text, text) to authenticated, service_role;

drop policy if exists payroll_runs_authenticated_all on public.payroll_runs;

create policy payroll_runs_select on public.payroll_runs
  for select to authenticated using (public.has_module_permission('payslips', 'read'));
create policy payroll_runs_insert on public.payroll_runs
  for insert to authenticated with check (public.has_module_permission('payslips', 'create'));
create policy payroll_runs_update on public.payroll_runs
  for update to authenticated
  using (public.has_module_permission('payslips', 'update'))
  with check (public.has_module_permission('payslips', 'update'));
create policy payroll_runs_delete on public.payroll_runs
  for delete to authenticated using (public.has_module_permission('payslips', 'delete'));
